const API=(window.APP_CONFIG?.API_BASE_URL||'').replace(/\/$/,'');
let token=sessionStorage.getItem('pilot_token')||'',me=null,staff=[],properties=[],channels=[],bookings=[],charts={},staffMonth='',propertyFilter='',kpiMonth='',calendarProperty='ALL',calendarStart='',calendarDays=21,calendarRange='21d',calendarRows=[],calendarQuery='',calendarSyncMessage='';
const fmtVND=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v||0));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isoToday=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const parseISODate=v=>{const [y,m,d]=String(v).split('-').map(Number);return new Date(y,m-1,d)};
const toISODate=d=>{const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const addDaysISO=(v,n)=>{const d=parseISODate(v);d.setDate(d.getDate()+Number(n||0));return toISODate(d)};
const diffDays=(a,b)=>Math.round((parseISODate(b)-parseISODate(a))/86400000);
const firstOfMonthISO=v=>{const d=parseISODate(v);d.setDate(1);return toISODate(d)};
const addMonthsISO=(v,n)=>{const d=parseISODate(v),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(n||0));const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return toISODate(d)};
const addYearsISO=(v,n)=>addMonthsISO(v,Number(n||0)*12);
function closeModal(id){document.getElementById(id).style.display='none'}
function msg(id,t,c=''){const e=document.getElementById(id);if(e)e.innerHTML=`<div class="notice ${c}">${t}</div>`}
async function api(path,opts={}){const headers={...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;if(opts.body&&!(opts.body instanceof FormData)){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}const r=await fetch(API+path,{...opts,headers});if(r.status===401){let m='Unauthorized';try{m=(await r.clone().json()).detail||m}catch{}if(path!='/api/auth/login'){logout();throw new Error('Session expired')}throw new Error(m)}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.json()).detail||m}catch{}throw new Error(m)}const ct=r.headers.get('content-type')||'';return ct.includes('application/json')?r.json():r}
function destroyChart(k){if(charts[k]){charts[k].destroy();delete charts[k]}}
function mkChart(id,key,type,labels,data,label='',opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets:[{label,data}]},options:{responsive:true,maintainAspectRatio:false,...opts}})}
function mkMultiChart(id,key,type,labels,datasets,opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,...opts}})}
async function download(path,filename){const headers={};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(API+path,{headers});if(r.status===401){logout();throw new Error('Session expired')}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.clone().json()).detail||m}catch{}throw new Error(m)}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function score(v){return v==null?'N/A':Number(v).toFixed(1)+'%'}
function kpiStatus(v){if(v==null)return 'N/A';return v>=90?'Excellent':v>=80?'Good':v>=70?'Fair':'Needs Improvement'}
async function login(){try{const j=await api('/api/auth/login',{method:'POST',body:{username:document.getElementById('login-user').value.trim(),password:document.getElementById('login-pass').value}});token=j.access_token;sessionStorage.setItem('pilot_token',token);await boot()}catch(e){msg('login-msg',esc(e.message),'error')}}
function logout(){sessionStorage.removeItem('pilot_token');token='';me=null;document.getElementById('app-view').classList.add('hidden');document.getElementById('login-view').classList.remove('hidden')}
async function boot(){if(!token)return;try{me=await api('/api/auth/me');document.getElementById('login-view').classList.add('hidden');document.getElementById('app-view').classList.remove('hidden');document.getElementById('whoami').textContent=`Signed in: ${me.username} — ${me.full_name} (${me.role})`;buildNav();await loadMasters();showView('dashboard')}catch(e){logout()}}
function buildNav(){let d=[['dashboard','📈 Dashboard'],['staff','👥 Staff'],['kpi','🏆 KPI Dashboard']];if(['manager','admin'].includes(me.role))d.push(['datamodel','🧩 Data Model']);d.push(['channels','🌐 Channels'],['segments','👨‍👩‍👧‍👦 Segments'],['financial','💰 Financial'],['stays','🏨 Stay Duration'],['calendar','🗓️ Lịch đặt phòng'],['bookings','📅 Bookings'],['properties','🏢 Properties']);if(me.role==='admin')d.push(['import','📥 Import']);if(['manager','admin'].includes(me.role))d.push(['export','📤 Export'],['auditlog','📋 Audit Log'],['validation','✅ Validation']);if(me.role==='admin')d.push(['auditpanel','🔍 Audit Panel'],['users','🔐 Users']);document.getElementById('nav').innerHTML=d.map(([i,l])=>`<button id="nav-${i}" onclick="showView('${i}')">${l}</button>`).join('')}
async function loadMasters(){[staff,properties,channels]=await Promise.all([api('/api/staff'),api('/api/properties'),api('/api/channels')])}
function showView(id){document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.getElementById(`nav-${id}`)?.classList.add('active');const f={dashboard:loadDashboard,staff:loadStaff,kpi:loadKPI,datamodel:loadDataModel,channels:loadChannels,segments:loadSegments,financial:loadFinancial,stays:loadStays,calendar:loadBookingCalendar,bookings:loadBookings,properties:loadProperties,import:loadImport,export:loadExport,auditlog:loadAudit,auditpanel:loadAuditPanel,validation:loadValidation,users:loadUsers}[id];if(f)f()}

async function loadDashboard(){const [d,ch,segs]=await Promise.all([api('/api/dashboard'),api('/api/analytics/channels'),api('/api/analytics/segments')]);document.getElementById('dashboard').innerHTML=`<h2>📈 Dashboard - Overview</h2><div class="cards">${[['Total',d.bookings],['Confirmed',d.confirmed],['Completed',d.completed],['Pending',d.pending],['Cancelled',d.cancelled],['Eligible Revenue',fmtVND(d.eligible_revenue)]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div></div>`).join('')}</div><h3>Performance Analysis</h3><div class="grid2"><div class="chart"><h3>📊 Booking Status</h3><canvas id="dash-status"></canvas></div><div class="chart"><h3>💰 Revenue by Channel</h3><canvas id="dash-revenue"></canvas></div></div><div class="grid2"><div class="chart"><h3>👥 Customer Segments</h3><canvas id="dash-segment"></canvas></div><div class="chart"><h3>🌐 Bookings by Channel</h3><canvas id="dash-channel"></canvas></div></div><div class="notice">Scope: ${me.role==='staff'?'your own bookings':'all staff bookings'}.</div>`;mkChart('dash-status','dashStatus','doughnut',['Confirmed','Completed','Pending','Cancelled'],[d.confirmed,d.completed,d.pending,d.cancelled]);mkChart('dash-revenue','dashRevenue','bar',ch.map(x=>x.channel),ch.map(x=>x.revenue/1e6),'Revenue (M)',{indexAxis:'y'});mkChart('dash-segment','dashSegment','pie',segs.map(x=>x.segment),segs.map(x=>x.bookings));mkChart('dash-channel','dashChannel','bar',ch.map(x=>x.channel),ch.map(x=>x.bookings),'Bookings')}

async function loadStaff(){const k=await api(`/api/kpi${staffMonth?`?month=${staffMonth}`:''}`);staff=await api('/api/staff');bookings=await api(`/api/bookings${staffMonth?`?month=${staffMonth}`:''}`);const km=new Map(k.rows.map(x=>[x.staff_id,x]));const propsByStaff={};for(const b of bookings){if(b.status==='cancelled')continue;(propsByStaff[b.staff_id]??=new Map()).set(b.property_id,b.property_name)}const months=k.evidence_months||[];document.getElementById('staff').innerHTML=`<h2>👥 Staff Management</h2><div class="notice"><strong>Staff are not assigned to one fixed Property.</strong> Property coverage is derived from Bookings for the selected period. Eligible revenue uses Confirmed + Completed bookings.</div><div class="toolbar">${me.role!=='staff'?'<button class="success" onclick="openStaffModal()">➕ Add Staff</button>':''}<label><strong>Filter Month:</strong></label><select id="staff-month" onchange="staffMonth=this.value;loadStaff()"><option value="">All evidence months</option>${months.map(m=>`<option ${m===staffMonth?'selected':''}>${m}</option>`).join('')}</select><strong>Total Staff: ${staff.length}</strong></div><div class="scroll"><table><thead><tr><th>Staff ID</th><th>Name</th><th>Properties Sold</th><th>Bookings</th><th>Revenue</th><th>KPI %</th><th>Status</th><th>Actions</th></tr></thead><tbody>${staff.map(s=>{const r=km.get(s.staff_id)||{}, ps=[...(propsByStaff[s.staff_id]?.entries()||[])];return `<tr><td>${s.staff_id}</td><td>${esc(s.staff_name)}</td><td>${ps.length?ps.map(([id,n])=>`<span class="badge" title="${id}">${esc(n)}</span>`).join(' '):'—'}</td><td>${bookings.filter(b=>b.staff_id===s.staff_id).length}</td><td>${fmtVND(r.revenue||0)}</td><td>${r.revenue_score==null?'N/A':r.revenue_score.toFixed(1)+'%'}</td><td>${kpiStatus(r.composite_kpi)}</td><td>${me.role==='staff'?'—':`<button class="warn small" onclick='openStaffModal(${JSON.stringify(s)})'>Edit</button><button class="danger small" onclick="deleteStaff('${s.staff_id}')">Delete</button>`}</td></tr>`}).join('')}</tbody></table></div><h3>Staff KPI Analytics</h3><div class="grid2"><div class="chart"><h3>📊 Top 10 Staff by KPI</h3><canvas id="staff-kpi-chart"></canvas></div><div class="chart"><h3>📈 KPI Trend (All Months)</h3><canvas id="staff-trend-chart"></canvas></div></div><div class="grid2"><div class="chart"><h3>💰 Eligible Revenue Contribution</h3><canvas id="staff-revenue-chart"></canvas></div><div class="chart"><h3>🎯 Booking Count by Staff</h3><canvas id="staff-bookings-chart"></canvas></div></div>`;
const ranked=[...k.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)).slice(0,10);mkChart('staff-kpi-chart','staffKpi','bar',ranked.map(r=>r.staff_name),ranked.map(r=>r.composite_kpi||0),'KPI',{indexAxis:'y'});mkChart('staff-revenue-chart','staffRevenue','doughnut',ranked.map(r=>r.staff_name),ranked.map(r=>r.revenue));mkChart('staff-bookings-chart','staffBookings','bar',ranked.map(r=>r.staff_name),ranked.map(r=>bookings.filter(b=>b.staff_id===r.staff_id).length),'Bookings');
if(months.length){const top=k.rows.slice(0,5);const series=[];for(const s of top){const vals=[];for(const m of months){const md=await api(`/api/kpi?month=${m}`);vals.push(md.rows.find(x=>x.staff_id===s.staff_id)?.composite_kpi||0)}series.push({label:s.staff_name,data:vals,fill:false,tension:.25})}mkMultiChart('staff-trend-chart','staffTrend','line',months,series,{plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,max:100}}})}}
function openStaffModal(s=null){const id=s?.staff_id||'';document.getElementById('dynamic-modal').innerHTML=`<div class="modal-card"><div class="modal-head"><h2>${s?'Edit':'Add'} Staff</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div class="form-row"><div class="form-group"><label>Staff ID</label><input id="s-id" value="${esc(id)}" ${s?'disabled':''}></div><div class="form-group"><label>Name</label><input id="s-name" value="${esc(s?.staff_name||'')}"></div></div><div class="form-row"><div class="form-group"><label>Team</label><input id="s-team" value="${esc(s?.team||'')}"></div><div class="form-group"><label>Monthly Revenue Target (VND)</label><input id="s-target" type="number" value="${s?.monthly_base_revenue_target_vnd||5000000}"></div></div><div class="form-group"><label>Active</label><select id="s-active"><option value="true" ${s?.active!==false?'selected':''}>Yes</option><option value="false" ${s?.active===false?'selected':''}>No</option></select></div><button class="success" onclick="saveStaff('${id}')">💾 Save</button></div>`;document.getElementById('dynamic-modal').style.display='block'}
async function saveStaff(existing=''){const body={staff_id:existing||document.getElementById('s-id').value.trim(),staff_name:document.getElementById('s-name').value.trim(),team:document.getElementById('s-team').value.trim(),start_date:null,active:document.getElementById('s-active').value==='true',monthly_base_revenue_target_vnd:+document.getElementById('s-target').value};try{await api(existing?`/api/staff/${existing}`:'/api/staff',{method:existing?'PUT':'POST',body});closeModal('dynamic-modal');await loadMasters();loadStaff()}catch(e){alert(e.message)}}
async function deleteStaff(id){if(!confirm(`Delete ${id}? If referenced, the backend will block deletion and you should set Active = No.`))return;try{await api(`/api/staff/${id}`,{method:'DELETE'});await loadMasters();loadStaff()}catch(e){alert(e.message)}}

async function loadKPI(){const first=await api('/api/kpi');const months=first.evidence_months||[];if(kpiMonth&&!months.includes(kpiMonth))kpiMonth='';document.getElementById('kpi').innerHTML=`<h2>🏆 Composite KPI Dashboard & Staff Ranking</h2><div class="notice">Composite KPI = Revenue 40% + Room Nights 20% + Conversion 15% + On-time Payment 15% + SLA 10%. Missing evidence remains N/A and weights are not redistributed.</div><div class="toolbar"><label><strong>Month:</strong></label><select id="kpi-month" onchange="kpiMonth=this.value;refreshKPI()"><option value="">All available months</option>${months.map(m=>`<option value="${m}" ${m===kpiMonth?'selected':''}>${m}</option>`).join('')}</select><button id="kpi-refresh-btn" onclick="refreshKPI()">🔄 Refresh Ranking</button><button class="success" onclick="exportKPI()">📥 Export Ranking CSV</button></div><div id="kpi-month-status" class="notice"></div><div id="kpi-body"></div>`;if(kpiMonth){await refreshKPI()}else{renderKPI(first)}}
async function refreshKPI(){const sel=document.getElementById('kpi-month');const btn=document.getElementById('kpi-refresh-btn');const m=sel?.value||'';kpiMonth=m;if(sel)sel.disabled=true;if(btn)btn.disabled=true;msg('kpi-month-status',`⏳ Loading KPI data for ${m||'all available months'}...`);try{const d=await api(`/api/kpi${m?`?month=${encodeURIComponent(m)}`:''}`);renderKPI(d)}catch(e){msg('kpi-month-status',`❌ ${esc(e.message)}`,'error')}finally{if(sel)sel.disabled=false;if(btn)btn.disabled=false}}
function renderKPI(d){const valid=d.rows.filter(r=>r.composite_kpi!=null).sort((a,b)=>b.composite_kpi-a.composite_kpi),avg=k=>{const a=d.rows.map(r=>r[k]).filter(v=>v!=null);return a.length?a.reduce((s,v)=>s+v,0)/a.length:0};const coverage=k=>d.rows.filter(r=>r[k]!=null).length;const periodLabel=d.month==='ALL'?'All available months':d.month;document.getElementById('kpi-month-status').innerHTML=`<strong>Selected period:</strong> ${periodLabel}. <strong>Available evidence months:</strong> ${(d.evidence_months||[]).join(', ')||'None'}.`;document.getElementById('kpi-body').innerHTML=`<div class="cards"><div class="card"><div class="label">Total Staff</div><div class="value">${d.rows.length}</div></div><div class="card"><div class="label">Scorable Staff</div><div class="value">${valid.length}</div></div><div class="card"><div class="label">Average Coverage</div><div class="value">${d.rows.length?(d.rows.reduce((s,r)=>s+r.coverage,0)/d.rows.length/5*100).toFixed(0):0}%</div></div></div><div class="grid2"><div class="chart"><h3>🏅 Top 10 Staff by Composite KPI — ${periodLabel}</h3><canvas id="kpi-rank"></canvas></div><div class="chart"><h3>📊 Average KPI Component Scores — ${periodLabel}</h3><div class="muted">Coverage: Revenue ${coverage('revenue_score')}; Room Nights ${coverage('room_nights_score')}; Conversion ${coverage('conversion_score')}; Payment ${coverage('payment_score')}; SLA ${coverage('sla_score')}</div><canvas id="kpi-components"></canvas></div></div><h3>Staff Ranking — ${periodLabel}</h3><div class="scroll"><table><thead><tr><th>Rank</th><th>Staff ID</th><th>Name</th><th>Revenue</th><th>Room Nights</th><th>Conversion</th><th>On-time Payment</th><th>SLA</th><th>Composite KPI</th><th>Status</th><th>Coverage</th></tr></thead><tbody>${[...d.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)).map((r,i)=>`<tr><td>${r.composite_kpi==null?'—':i+1}</td><td>${r.staff_id}</td><td>${esc(r.staff_name)}</td><td>${score(r.revenue_score)}</td><td>${score(r.room_nights_score)}</td><td>${score(r.conversion_score)}</td><td>${score(r.payment_score)}</td><td>${score(r.sla_score)}</td><td>${r.composite_kpi==null?'N/A':r.composite_kpi.toFixed(1)}</td><td>${kpiStatus(r.composite_kpi)}</td><td>${r.coverage}/5</td></tr>`).join('')}</tbody></table></div>`;mkChart('kpi-rank','kpiRank','bar',valid.slice(0,10).map(r=>`${r.staff_id} ${r.staff_name}`),valid.slice(0,10).map(r=>r.composite_kpi),'Composite KPI',{indexAxis:'y',scales:{x:{beginAtZero:true,max:100}}});mkChart('kpi-components','kpiComp','bar',['Revenue','Room Nights','Conversion','On-time Payment','SLA'],['revenue_score','room_nights_score','conversion_score','payment_score','sla_score'].map(avg),'Score %',{scales:{y:{beginAtZero:true,max:100}}})}
function exportKPI(){const m=document.getElementById('kpi-month')?.value||'';download(`/api/kpi/export-csv${m?`?month=${m}`:''}`,`kpi_ranking_${m||'ALL'}_v1.0.2.csv`).catch(e=>alert(e.message))}

async function loadDataModel(){const d=await api('/api/data-model');document.getElementById('datamodel').innerHTML=`<h2>🧩 V1.0.2f Pilot Data Model</h2><div class="notice">Normalized backend entities are validated against PK/FK rules in the centralized database. Transactional history is never silently deleted by master synchronization.</div><div class="cards"><div class="card"><div class="label">Errors</div><div class="value">${d.error_count}</div></div><div class="card"><div class="label">Warnings</div><div class="value">${d.warning_count}</div></div></div><div class="toolbar"><button class="success" onclick="refreshDataModel()">🔄 Rebuild / Refresh Data Model</button><button class="purple" onclick="syncMasterDeps()">🔗 Sync Master Dependencies</button><button onclick="checkDataModel()">✅ Check Keys & Relations</button><button onclick="exportDataModelJson()">📥 Export Data Model JSON</button><button onclick="exportIntegrityCsv()">📥 Export Integrity Report CSV</button></div><div id="dm-msg"></div><div class="grid2"><div><h3>Entity Overview</h3><div class="scroll"><table><thead><tr><th>Entity</th><th>Primary Key</th><th>Rows</th><th>Status</th></tr></thead><tbody>${d.entities.map(x=>`<tr><td>${x.entity}</td><td>${x.primary_key}</td><td>${x.rows}</td><td>${d.issues.some(i=>i.entity===x.entity)?'⚠️ Review':'✅ PASS'}</td></tr>`).join('')}</tbody></table></div></div><div><h3>Relationship Rules</h3><div class="notice">Bookings.staff_id → Staff.staff_id<br>Staff ↔ Properties through Bookings<br>Bookings.property_id → Properties.property_id<br>Bookings.room_type_id → Room Types(property_id + room_type_id)<br>KPI Targets.staff_id → Staff.staff_id<br>Users.staff_id → Staff.staff_id (optional for manager/admin)</div></div></div><h3>Entity Tables</h3><div id="dm-entities"></div><h3>Integrity Issues</h3><div class="scroll"><table><thead><tr><th>Severity</th><th>Entity</th><th>Record ID</th><th>Rule</th><th>Issue</th></tr></thead><tbody>${d.issues.length?d.issues.map(i=>`<tr><td>${i.severity}</td><td>${i.entity}</td><td>${i.record_id}</td><td>${i.rule}</td><td>${esc(i.issue)}</td></tr>`).join(''):'<tr><td colspan="5">✅ No integrity issues.</td></tr>'}</tbody></table></div>`;await renderDataModelEntities()}
async function renderDataModelEntities(){const [u,s,p,c]=await Promise.all([me.role==='admin'?api('/api/users'):Promise.resolve([]),api('/api/staff'),api('/api/properties'),api('/api/channels')]);const el=document.getElementById('dm-entities');if(!el)return;el.innerHTML=`${me.role==='admin'?`<div class="chart"><h3>Users</h3><div class="scroll"><table><thead><tr><th>User ID</th><th>Name</th><th>Role</th><th>Staff ID</th><th>Active</th></tr></thead><tbody>${u.map(x=>`<tr><td>${x.username}</td><td>${esc(x.full_name)}</td><td>${x.role}</td><td>${x.staff_id||'—'}</td><td>${x.active?'Yes':'No'}</td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="grid2"><div class="chart"><h3>Staff</h3><div class="scroll"><table><thead><tr><th>Staff ID</th><th>Name</th><th>Team</th><th>Target</th></tr></thead><tbody>${s.map(x=>`<tr><td>${x.staff_id}</td><td>${esc(x.staff_name)}</td><td>${esc(x.team)}</td><td>${fmtVND(x.monthly_base_revenue_target_vnd)}</td></tr>`).join('')}</tbody></table></div></div><div class="chart"><h3>Properties</h3><div class="scroll"><table><thead><tr><th>ID</th><th>Name</th><th>Status</th><th>Total Rooms</th></tr></thead><tbody>${p.map(x=>`<tr><td>${x.property_id}</td><td>${esc(x.property_name)}</td><td>${x.active?'Active':'Inactive'}</td><td>${x.total_rooms}</td></tr>`).join('')}</tbody></table></div></div></div><div class="chart"><h3>Room Types & Inventory</h3><div class="scroll"><table><thead><tr><th>Property</th><th>Room Type</th><th>Name</th><th>Quantity</th></tr></thead><tbody>${p.flatMap(x=>x.room_types.map(r=>`<tr><td>${x.property_id}</td><td>${r.room_type_id}</td><td>${esc(r.room_type_name)}</td><td>${r.quantity}</td></tr>`)).join('')}</tbody></table></div></div><div class="chart"><h3>Channels</h3><div class="scroll"><table><thead><tr><th>Channel ID</th><th>Name</th><th>Commission</th><th>SLA</th></tr></thead><tbody>${c.map(x=>`<tr><td>${x.channel_id}</td><td>${esc(x.channel_name)}</td><td>${(x.commission_rate*100).toFixed(0)}%</td><td>${x.response_sla_minutes} min</td></tr>`).join('')}</tbody></table></div></div>`}
async function refreshDataModel(){try{await loadDataModel();msg('dm-msg','✅ Data Model refreshed from the centralized database.','successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function checkDataModel(){try{const d=await api('/api/data-model');await loadDataModel();const t=(d.error_count===0&&d.warning_count===0)?'✅ PK/FK check PASS — no integrity issues.':`⚠️ Integrity check completed: ${d.error_count} error(s), ${d.warning_count} warning(s).`;msg('dm-msg',t,d.error_count?'error':'successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function syncMasterDeps(){try{const r=await api('/api/data-model/sync-master-dependencies',{method:'POST'});await loadDataModel();msg('dm-msg',`✅ Master dependency sync completed. Removed orphan KPI targets: ${r.removed_kpi_targets}. ${esc(r.note)}`,'successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
async function exportDataModelJson(){try{await download('/api/data-model/export-json','data_model_v1.0.2f.json');msg('dm-msg','✅ Data Model JSON exported.','successbox')}catch(e){msg('dm-msg',esc(e.message),'error')}}
